import { projectSchema, type Project, type ProjectInput, type Category } from "@/lib/schemas";

/**
 * Portfolio projects, in display order. Only real QuadTricks projects belong here.
 * Never add invented clients, results or quotes.
 *
 * Fields worth knowing:
 *  - liveUrl:        live website or app store link. TODO for each project below; the
 *                    "Visit the website" / "Get the app" button appears once it is set.
 *  - conceptVisuals: true while the images are illustrative mockups (generated by
 *                    scripts/generate-concept-visuals.mjs). Set to false when you swap in
 *                    real screenshots, and the "concept visuals" note disappears.
 *  - year, tech:     optional; hidden when not given.
 *  - flagship:       optional extras (video, beforeAfter, timeline, verified outcome, real quote).
 *
 * Images live in public/work/<slug>/ as WebP. Website covers are 1600x1000; app covers are
 * portrait 900x1800 so they fill the phone frame.
 */
const web = (slug: string, file: string, alt: string) => ({ src: `/work/${slug}/${file}.webp`, alt, width: 1600, height: 1000 });
const phone = (slug: string, alt: string) => ({ src: `/work/${slug}/cover.webp`, alt, width: 900, height: 1800 });

